/** Helper: title for a lesson, with PT-BR fallback. */
export function licaoTitulo(num: number, locale: Locale, fallback: string): string {
  return LICAO_TITULO_I18N[num]?.[locale] ?? LICAO_TITULO_I18N[num]?.['pt-BR'] ?? fallback
}

/** Helper: topicos for a lesson, with PT-BR fallback. */
export function licaoTopicos(num: number, locale: Locale, fallback: string): string {
  return LICAO_TOPICOS_I18N[num]?.[locale] ?? LICAO_TOPICOS_I18N[num]?.['pt-BR'] ?? fallback
}
